<script setup lang="ts">import type {Run} from '../types/domain';import Table from './common/Table.vue';import Badge from './common/Badge.vue';import {date} from '../utils/format';defineProps<{runs:Run[]}>();defineEmits<{select:[run:Run]}>()</script><template><Table :headers="['校样编号 / 研究','状态','参考 / 候选','建立时间','']"><tr v-for="r in runs" :key="r.id"><td><small>PROOF / {{String(r.id).padStart(3,'0')}}</small><strong>{{r.name}}</strong></td><td><Badge :status="r.status"/></td><td>{{r.result.reference_n??'—'}} / {{r.result.candidate_n??'—'}}</td><td class="mono">{{date(r.created_at)}}</td><td><button class="text-button" @click="$emit('select',r)">阅读校样 ↗</button></td></tr></Table></template>
